575	/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
576	/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` has an
577	/// earlier `ToolCall` and is the only result for its call id.
578	fn assert_tool_calls_paired(messages: &[Item]) {
579	    let mut calls: Vec<&str> = Vec::new();
580	    let mut results: Vec<&str> = Vec::new();
581	    for item in messages {
582	        match item {
583	            Item::ToolCall { call_id, .. } => calls.push(call_id),
584	            Item::ToolResult { call_id, .. } => {
585	                assert!(
586	                    calls.contains(&call_id.as_str()),
587	                    "result {call_id} has no earlier call: {messages:?}"
588	                );
589	                assert!(
590	                    !results.contains(&call_id.as_str()),
591	                    "call {call_id} has two results: {messages:?}"
592	                );
593	                results.push(call_id);
594	            }
595	            _ => {}
596	        }
597	    }
598	    for (i, item) in messages.iter().enumerate() {
599	        let Item::ToolCall { call_id, .. } = item else {
600	            continue;
601	        };
602	        let mut paired = false;
603	        for later in &messages[i + 1..] {
604	            match later {
605	                Item::ToolResult { call_id: id, .. } if id == call_id => {
606	                    paired = true;
607	                    break;
608	                }
609	                Item::UserMessage { .. } | Item::AssistantMessage { .. } => break,
610	                _ => {}
611	            }
612	        }
613	        assert!(paired, "tool call {call_id} is not paired: {messages:?}");
614	    }
615	}
