657	async fn handoff_session_with(path: &[&str], leaf_turn: Vec<ModelEvent>) -> Arc<MemorySession> {
658	    let leaf = path.len() - 1;
659	    let mut agent: Arc<dyn Agent<()>> = Arc::new(
660	        LlmAgent::builder::<()>()
661	            .name(path[leaf])
662	            .shared_model(MockModel::with_scripts(vec![leaf_turn]))
663	            .shared_tool(MockTool::new("b", serde_json::json!({})) as Arc<dyn Tool<()>>)
664	            .build(),
665	    );
666	    for i in (0..leaf).rev() {
667	        agent = Arc::new(
668	            LlmAgent::builder::<()>()
669	                .name(path[i])
670	                .shared_model(MockModel::with_scripts(vec![transfer_turn(
671	                    &transfer_id(i),
672	                    path[i + 1],
673	                )]))
674	                .shared_handoff(agent)
675	                .build(),
676	        );
677	    }
678	    let session = Arc::new(MemorySession::new());
679	    let ctx = session_ctx(&session).with_deferred_tool_calls(true);
680	    let mut recorder = SessionRecorder::new(path[0]).with_deferral_slot(ctx.deferral_handle());
681	    let input = AgentInput::from_user_text("hi");
682	    recorder.record_input(&input.messages);
683	    let events = agent
684	        .run(ctx, input)
685	        .await
686	        .expect("run starts")
687	        .collect::<Vec<_>>()
688	        .await;
689	    assert!(
690	        matches!(events.last(), Some(AgentEvent::RunDeferred { .. })),
691	        "{events:?}"
692	    );
693	    for ev in &events {
694	        recorder.observe(ev);
695	    }
696	    session.append(&recorder.drain()).await.unwrap();
697	    session
698	}
