700	/// As [`handoff_session`], but the log has no result for the transfer calls
701	/// (`t1`, `t2`, ...). The session recorder closes them at the end of the
702	/// run; a log from another writer can leave them open.
703	async fn open_transfer_session(path: &[&str]) -> Arc<MemorySession> {
704	    let recorded = handoff_session(path).await.events(None).await.unwrap();
705	    let events: Vec<SessionEvent> = recorded
706	        .into_iter()
707	        .filter(|e| {
708	            !matches!(e, SessionEvent::ToolReturned { call_id, .. } if call_id.starts_with('t'))
709	        })
710	        .collect();
711	    let session = Arc::new(MemorySession::new());
712	    session.append(&events).await.unwrap();
713	    session
714	}
