716	/// Counts `OnHandoff` and records each `OnSubagentStop` agent.
717	#[derive(Default)]
718	struct HandoffCounts {
719	    on_handoff: Mutex<usize>,
720	    subagent_stops: Mutex<Vec<String>>,
721	}
722	
723	struct CountHandoffs(Arc<HandoffCounts>);
724	
725	#[async_trait]
726	impl Hook<()> for CountHandoffs {
727	    async fn on_event(&self, _: &RunContext<()>, event: &HookEvent) -> HookDecision {
728	        match event {
729	            HookEvent::OnHandoff { .. } => *self.0.on_handoff.lock().unwrap() += 1,
730	            HookEvent::OnSubagentStop { agent } => {
731	                self.0.subagent_stops.lock().unwrap().push(agent.clone());
732	            }
733	            _ => {}
734	        }
735	        HookDecision::Allow
736	    }
737	}
