739	/// The index of the `ToolOutputItem` for `call_id`.
740	fn output_index(events: &[AgentEvent], call_id: &str) -> usize {
741	    events
742	        .iter()
743	        .position(|e| {
744	            matches!(e, AgentEvent::ToolOutputItem { item: Item::ToolResult { call_id: id, .. } }
745	                if id == call_id)
746	        })
747	        .unwrap_or_else(|| panic!("no ToolOutputItem for {call_id}: {events:?}"))
748	}
