750	/// The transfer call `call_id` in `messages` is directly followed by the
751	/// result `agent no longer available: {name}`.
752	fn assert_transfer_closed(messages: &[Item], call_id: &str, name: &str) {
753	    let at = messages
754	        .iter()
755	        .position(|i| matches!(i, Item::ToolCall { call_id: id, .. } if id == call_id))
756	        .unwrap_or_else(|| panic!("no ToolCall {call_id}: {messages:?}"));
757	    match messages.get(at + 1) {
758	        Some(Item::ToolResult {
759	            call_id: id,
760	            content,
761	        }) if id == call_id => assert_eq!(
762	            text_of(content),
763	            format!("agent no longer available: {name}")
764	        ),
765	        other => panic!("{call_id} is not closed directly after its call: {other:?}"),
766	    }
767	}
