769	/// The result for `call_id` in `messages` is at the call index + 1.
770	fn assert_result_adjacent(messages: &[Item], call_id: &str) {
771	    let call = messages
772	        .iter()
773	        .position(|i| matches!(i, Item::ToolCall { call_id: id, .. } if id == call_id))
774	        .unwrap_or_else(|| panic!("no ToolCall {call_id}: {messages:?}"));
775	    let result = messages
776	        .iter()
777	        .position(|i| matches!(i, Item::ToolResult { call_id: id, .. } if id == call_id))
778	        .unwrap_or_else(|| panic!("no ToolResult {call_id}: {messages:?}"));
779	    assert_eq!(result, call + 1, "{call_id}: {messages:?}");
780	}
