805	async fn resume_handoff(
806	    session: &Arc<MemorySession>,
807	    root: &str,
808	    agent: &impl Agent<()>,
809	) -> Vec<AgentEvent> {
810	    resume_handoff_with(session, root, agent, session_ctx(session)).await
