813	/// As [`resume_handoff`], with the run context `ctx`.
814	async fn resume_handoff_with(
815	    session: &Arc<MemorySession>,
816	    root: &str,
817	    agent: &impl Agent<()>,
818	    ctx: RunContext<()>,
819	) -> Vec<AgentEvent> {
820	    let (input, plan) = resume_input(session, root, ToolResolution::Approved).await;
821	    let mut recorder = SessionRecorder::new(root).with_resume_plan(&plan);
822	    recorder.record_input(&input.messages);
823	    let events = run_events(agent, ctx, input).await;
824	    for ev in &events {
825	        recorder.observe(ev);
826	    }
827	    let resumed = recorder.drain();
828	    session.append(&resumed).await.unwrap();
829	    assert!(
830	        open_deferrals(&session.events(None).await.unwrap()).is_empty(),
831	        "{resumed:?}"
832	    );
833	    events
834	}
